#!/bin/zsh
# 英语学习模式：英文素材勾选后整理出单词分级、短语、难句解析。
cd "$(dirname "$0")"
gen() {
  local name=$1; local prompt=$2
  [ -f "$name.png" ] && return
  local t0=$(date +%s)
  codex exec --skip-git-repo-check --ephemeral -c 'model_reasoning_effort="low"' -C "$PWD" -s workspace-write \
    "请使用内置的 image_gen 工具生成一张高保真 UI 设计稿（像设计师在 Figma 里做的最终稿截图，正视图、不要透视、纯浅灰背景上只放这一个窗口）：$prompt 生成后把最终图片复制到当前目录，命名为 $name.png，然后只回复文件名。" < /dev/null > "$name.log" 2>&1
  echo "$name $(( $(date +%s) - t0 ))s $([ -f $name.png ] && echo ok || echo FAIL)"
}
S="这是 macOS 桌面应用「豆仓」（把录音转成文字、整理成纪要）。浅色模式。设计语言：苹果 macOS 最新系统的风格加乔纳森·艾维式的克制——圆角卡片、细分隔线、说明是小号灰字、对齐严谨、留白舒服。配色严格限定：暖灰纸色背景（#FAF9F7）、卡片纯白、深暖灰文字（#1C1917）、唯一强调色玫瑰红（#F43F5E，用在主按钮、选中状态）；绝对不要蓝色、紫色、青色、彩虹色。界面文字全部是简体中文，字体像苹方，清晰可读、没有乱码。"
gen ui_study "【录音详情 · 纪要页签 · 英语学习模式开着】一个 macOS 窗口宽约 1260：左边窄侧栏，中间素材列表（选中「6 Minute English · Learning from different generations」，来源小胶囊「Apple 播客」），右边详情：顶部元信息「播客 · Apple 播客 · 10 分钟」，大标题，分段控件「纪要（选中）/ 文字稿 / 改写」。纪要页签顶上一行：左边一个勾选框「☑ 英语学习模式」（勾上，玫瑰红），旁边灰色小字「按学英语的需要整理：单词分级、短语、难句。不勾就是普通纪要」，右边一个小按钮「重新整理」。下面依次是白色圆角卡片（圆角 10）：① 「难度概览」卡：一句话「整体 B2 中高级 · 语速约 160 词/分」，下面一条横向分段色条显示词汇分级占比 A1–A2 / B1 / B2 / C1–C2（用暖灰到玫瑰红的渐变色块，不用蓝紫），每段下方小字百分比。② 「重点单词 · 24 个」卡：一个表格样式列表，每行：单词粗体「generation」、音标灰字「/ˌdʒenəˈreɪʃn/」、词性「n.」、等级小胶囊「B1」（不同等级不同深浅的暖色）、中文释义「一代人；世代」，最右一个小播放图标表示「听原句」；上方有一排筛选小胶囊「全部 · B2 及以上 · C1–C2」。③ 「短语搭配 · 8 个」卡：每行「learn from each other — 互相学习」，下面一行灰色斜体原句。④ 「难句解析 · 5 句」卡：每块左边时间「02:14」，英文原句，下面中文译文，再下面一个浅暖灰小框写「结构：主句 … ＋ 定语从句 who …；要点：have something to learn from 表示『有值得学习的地方』」，右上角小按钮「▶ 听这句」。整体克制、学习卡片感，只有勾选框、等级胶囊和播放图标用玫瑰红点缀。$S"
